package io.github.kotlinmania.rand.rngs

import io.github.kotlinmania.rand.CryptoRng
import io.github.kotlinmania.rand.Rng
import io.github.kotlinmania.threadlocal.ThreadLocal

/**
 * Number of generated bytes after which to reseed `ThreadRng`.
 */
internal const val THREAD_RNG_RESEED_THRESHOLD: ULong = 65536uL

private val threadRngKey: ThreadLocal<ReseedingRng<StdRng, OsRng>> = ThreadLocal()

/**
 * A reference to the thread-local generator.
 */
public class ThreadRng internal constructor(
    private val rng: ReseedingRng<StdRng, OsRng>,
) : CryptoRng,
    Rng {
    public constructor() : this(currentThreadRng())

    /**
     * Immediately reseed the generator.
     */
    public fun reseed() {
        rng.reseed()
    }

    override fun nextU32(): UInt = rng.nextU32()

    override fun nextU64(): ULong = rng.nextU64()

    override fun fillBytes(dest: ByteArray) {
        rng.fillBytes(dest)
    }

    override fun toString(): String = "ThreadRng { .. }"

    public companion object {
        public fun default(): ThreadRng = rng()
    }
}

private fun currentThreadRng(): ReseedingRng<StdRng, OsRng> =
    threadRngKey.getOr {
        ReseedingRng.std(THREAD_RNG_RESEED_THRESHOLD, OsRng)
    }

/**
 * Access a fast, pre-initialized generator.
 *
 * This is a handle to the local [ThreadRng].
 */
public fun rng(): ThreadRng = ThreadRng(currentThreadRng())

/**
 * Access the thread-local generator.
 *
 * Use [rng] instead.
 */
@Deprecated("Renamed to rng", ReplaceWith("rng()"))
public fun threadRng(): ThreadRng = rng()
